sys_script_include.script:
var EventsRefQual = Class.create();
EventsRefQual.prototype = {
    initialize: function() {},

    // Get the logged-in Employee's record.
    _getCurrentEmployee: function() {
        var employeeGR = new GlideRecord(
            'x_1790229_edusph_0_employee'
        );

        employeeGR.addQuery('user', gs.getUserID());
        employeeGR.setLimit(1);
        employeeGR.query();

        if (employeeGR.next()) {
            return employeeGR;
        }

        return null;
    },

    // Get the logged-in Employee's College.
    _getCurrentEmployeeCollege: function() {
        var employeeGR = this._getCurrentEmployee();

        if (!employeeGR) {
            return '';
        }

        return employeeGR.getValue('college') || '';
    },

    // Get sys_user IDs having any of the supplied actual roles.
    _getUsersWithRoles: function(roleNames) {
        var userIds = [];

        var roleGR = new GlideRecord('sys_user_has_role');
        roleGR.addQuery('role.name', 'IN', roleNames.join(','));
        roleGR.query();

        while (roleGR.next()) {
            var userId = roleGR.getValue('user');

            if (userId && userIds.indexOf(userId) === -1) {
                userIds.push(userId);
            }
        }

        return userIds;
    },

    // Return active Employees in the specified College
    // whose linked Users have at least one required role.
    _getEmployeesForCollegeAndRoles: function(collegeId, roleNames) {
        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        var userIds = this._getUsersWithRoles(roleNames);

        if (userIds.length === 0) {
            return 'sys_idISEMPTY';
        }

        var employeeIds = [];

        var employeeGR = new GlideRecord(
            'x_1790229_edusph_0_employee'
        );

        employeeGR.addQuery('active', true);
        employeeGR.addQuery('college', collegeId);
        employeeGR.addQuery('user', 'IN', userIds.join(','));
        employeeGR.query();

        while (employeeGR.next()) {
            employeeIds.push(employeeGR.getUniqueValue());
        }

        if (employeeIds.length === 0) {
            return 'sys_idISEMPTY';
        }

        return 'sys_idIN' + employeeIds.join(',');
    },

    // 1. Event -> Event Head
    getEventHeadEmployees: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        return this._getEmployeesForCollegeAndRoles(
            collegeId,
            ['x_erp.event_head']
        );
    },

    // 2. Event -> Venue (Room)
    getRoomsForCurrentEmployeeCollege: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'college=' + collegeId;
    },

    // 3. Event -> College
    getCurrentEmployeeCollege: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'sys_id=' + collegeId;
    },

    // 4. EventBudget -> Event
    getEventsForCurrentEmployeeCollege: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'college=' + collegeId;
    },

    // 5. EventBudget -> Approver
    getEventBudgetApprovers: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        return this._getEmployeesForCollegeAndRoles(
            collegeId,
            [
                'x_erp.principal',
                'x_erp.dean',
                'x_erp.finance'
            ]
        );
    },

    // 6. EventBudget -> Requested By
    getEventBudgetRequestedByEmployees: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'active=true^college=' + collegeId;
    },

    // 7. EventResource -> Event
    getEventsForEventResource: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'college=' + collegeId;
    },

    // 8. EventResource -> Asset
    // DEFERRED: intentionally returns no records.
    getAssetsForEventResource: function() {
        return '';
    },

    // 9. EventRegistration -> Event
    getEventsForEventRegistration: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'college=' + collegeId;
    },

    // 10. EventRegistration -> Student
    getStudentsForEventRegistration: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'college=' + collegeId;
    },

    // 11. EventRegistration -> Fee (StudentFee)
    // Filter by the Student selected on the current form.
    getFeesForSelectedStudent: function(studentId) {
        if (!studentId) {
            return 'sys_idISEMPTY';
        }

        return 'student=' + studentId;
    },

    // 12. EventRegistration -> Payment Transaction
    // DEFERRED: intentionally returns no records.
    getPaymentTransactionsForEventRegistration: function() {
        return '';
    },

    // 13. EventAttendance -> Registration
    getRegistrationsForEventAttendance: function() {
        var collegeId = this._getCurrentEmployeeCollege();

        if (!collegeId) {
            return 'sys_idISEMPTY';
        }

        return 'event.college=' + collegeId;
    },

    // 14. EventAttendance -> Scanner
    // DEFERRED: intentionally returns no records.
    getScannersForEventAttendance: function() {
        return '';
    },

    type: 'EventsRefQual'
};
